// Checks the retiming in docs/index.html against docs/timing_cases.json.
//
// Those expected values were generated by the Python sync.py this tool replaced, while it
// was still in the tree, so they pin the browser to the behaviour the CLI had rather than
// to whatever the page happens to do today.
//
//   node docs/test_timing.mjs

import { readFileSync, writeFileSync, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));

// Pull the shared region out of the page so the test runs against the shipped bytes
const page = readFileSync(join(here, "index.html"), "utf8");
const start = page.indexOf("/* --- timing:start");
const end = page.indexOf("/* --- timing:end");
if (start < 0 || end < 0) throw new Error("timing sentinels not found in index.html");

const scratch = mkdtempSync(join(tmpdir(), "gifsync-timing-"));
const modulePath = join(scratch, "timing.mjs");
writeFileSync(modulePath, page.slice(start, end));
const { getDurations, getFrameOrder } = await import(modulePath);

const { cases, rejected } = JSON.parse(readFileSync(join(here, "timing_cases.json"), "utf8"));

let failures = 0;

for (const c of cases) {
  const durations = getDurations(c.beats, c.msPerBeat, c.nFrames, c.interpolation);
  const order = getFrameOrder(c.beats[0], c.nFrames);

  const lengthOk = durations.length === c.durations.length;
  const worst = lengthOk ? Math.max(...durations.map((d, i) => Math.abs(d - c.durations[i]))) : Infinity;
  const orderOk = order.length === c.order.length && order.every((f, i) => f === c.order[i]);

  if (!lengthOk || worst > 1e-9 || !orderOk) {
    failures++;
    console.log(`FAIL ${c.interpolation} beats=[${c.beats}] msPerBeat=${c.msPerBeat} nFrames=${c.nFrames}`);
    console.log(`  got  ${durations.slice(0, 8).map((d) => d.toFixed(6))}`);
    console.log(`  want ${c.durations.slice(0, 8).map((d) => d.toFixed(6))}`);
    console.log(`  worst delta ${worst}, frame order matches: ${orderOk}`);
  }
}

// The input the CLI refused, the page has to refuse too
for (const beats of rejected) {
  let threw = false;
  try { getDurations(beats, 500, 16, "linear"); } catch { threw = true; }
  if (!threw) { failures++; console.log(`FAIL [${beats}] was accepted but should not be`); }
}

console.log(`${cases.length} timing cases + ${rejected.length} rejection cases, ${failures} failures`);
process.exit(failures ? 1 : 0);
